import {renderServiceStatus} from "./service-status.js";
import { escapeHtml as esc } from './message-format.js';
const BACKEND_CANISTER_ID = "__BACKEND_CANISTER_ID__";
const API = `https://${BACKEND_CANISTER_ID}.icp.net/support/v1`;
const root = document.getElementById('support');
const parts=location.hash.slice(1).split('/');
let pending=null, schema=null, capability='', ticketId='', poll=null, publicStatusGeneration=0;
const random = () => Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
const status = text => { const el=document.getElementById('status');if(el)el.textContent=text; };
async function request(path,{body,token}={}) {
  const controller=new AbortController(), timer=setTimeout(()=>controller.abort(),30000);
  try { const response=await fetch(API+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',signal:controller.signal});
    const result=await response.json();if(!response.ok){const e=new Error(result.error||'Support is unavailable. Please try again.');e.status=response.status;throw e;}return result;
  } finally { clearTimeout(timer); }
}
function privacyText(p) { return p?`<p class="hint">We automatically delete completed requests after ${esc(p.completedDays)} days and open requests after ${esc(p.inactiveDays)} days without activity. A justified, time-limited hold may extend this.${/^https:\/\//.test(p.noticeUrl||'')?` <a href="${esc(p.noticeUrl)}" target="_blank" rel="noopener noreferrer">Privacy notice ↗</a>`:''}</p>`:''; }
function saveJson(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function unavailable(){clearInterval(poll);capability='';pending=null;history.replaceState(null,'',location.pathname);document.title='Customer support';root.innerHTML='<span class="eyebrow">Customer support</span><h1>This ticket is no longer available.</h1><p>It may have been deleted, or its private link may have expired or been replaced. Contact the product’s support team if you still need help.</p>';}
const field = f => {const attrs=`id="field-${esc(f.key)}" name="${esc(f.key)}" ${f.required?'required':''}`;return `<label for="field-${esc(f.key)}">${esc(f.title)}${f.required?'':' (optional)'}</label>${f.kind==='textarea'?`<textarea ${attrs} maxlength="2000"></textarea>`:f.kind==='select'?`<select ${attrs}><option value="">Choose…</option>${f.options.map(o=>`<option>${esc(o)}</option>`).join('')}</select>`:f.kind==='bool'?`<select ${attrs}><option value="">Choose…</option><option value="true">Yes</option><option value="false">No</option></select>`:`<input ${attrs} type="${f.kind==='date'?'date':'text'}" maxlength="2000">`}`;};
async function form(widgetId) {
  schema=await request(`/widgets/${widgetId}/schema`);
  document.title=schema.name+' · Support';
  const types=schema.requestTypes||[{id:null,name:'General support',fields:schema.fields}];
  let selected=types.find(t=>String(t.id)===parts[2])||types.find(t=>t.id===schema.defaultTypeId)||types[0];
  root.innerHTML=`<span class="eyebrow">${esc(schema.name)} · Support</span><h1>How can we help?</h1><p class="lead">${esc(schema.description||'Tell us what happened. Our team will take it from here.')}</p>${schema.serviceStatus?`<aside class="ss-widget-notice"><strong>${schema.serviceStatus.hasActiveNotice?'A known service issue may affect this request.':'Check service status before opening a request.'}</strong><a href="./support.html#status/${encodeURIComponent(schema.serviceStatus.slug)}" target="_blank" rel="noopener noreferrer">Service status ↗</a></aside>`:''}<form id="requestForm" class="card">${types.length>1?`<label for="requestType">Request type</label><select id="requestType">${types.map(t=>`<option value="${esc(t.id)}" ${t===selected?'selected':''}>${esc(t.name)}</option>`).join('')}</select><p class="hint" id="typeDescription">${esc(selected.description||'')}</p>`:''}<div class="row"><div><label for="name">Your name</label><input id="name" autocomplete="name" required maxlength="100"></div><div><label for="email">Email address</label><input id="email" type="email" autocomplete="email" required maxlength="254"></div></div><label for="subject">Brief summary</label><input id="subject" required maxlength="160"><label for="body">A little more detail</label><textarea id="body" required maxlength="8000" placeholder="What happened, and what were you expecting?"></textarea><div id="typeFields">${selected.fields.map(field).join('')}</div><p class="hint">Please do not include passwords, payment details or other sensitive information. You’ll receive a private link for replies and status. No email is sent.</p>${privacyText(schema.privacy)}<button id="send" type="submit">Send request →</button><p id="status" class="status" role="status"></p></form>`;
  const picker=document.getElementById('requestType');if(picker)picker.onchange=()=>{selected=types.find(t=>String(t.id)===picker.value);document.getElementById('typeFields').innerHTML=selected.fields.map(field).join('');document.getElementById('typeDescription').textContent=selected.description||'';};
  document.getElementById('requestForm').onsubmit=async e=>{
    e.preventDefault();const button=document.getElementById('send');if(button.disabled)return;button.disabled=true;status('Sending your request…');
    const get=id=>document.getElementById(id).value;
    if(!pending)pending={name:get('name'),email:get('email'),subject:get('subject'),body:get('body'),revision:schema.revision,...(selected.id===null?{}:{typeId:selected.id}),clientToken:random(),fields:Object.fromEntries(selected.fields.map(f=>[f.key,get('field-'+f.key)]))};
    // An uncertain transport response retries the exact payload/token, never another ticket.
    [...e.target.elements].forEach(x=>x.disabled=true);
    try {const r=await request(`/widgets/${widgetId}/tickets`,{body:pending});pending=null;capability=r.url.split('/').at(-1);ticketId=String(r.id);history.replaceState(null,'',`#ticket/${ticketId}/${capability}`);confirmation(r);}
    catch(err){status(err.name==='AbortError'?'The request is taking longer than expected. Retry safely below.':err.message);if(err.status){pending=null;[...e.target.elements].forEach(x=>x.disabled=false);}button.disabled=false;button.textContent=pending?'Retry sending':'Send request →';if(err.status===409){status(err.message+' Copy your message before reloading this form.');}}
  };
}
function confirmation(r) {
  root.innerHTML=`<span class="eyebrow">Request received · ${esc(r.key)}</span><h1>You’re in the right place.</h1><p class="lead">Our team will respond in your private conversation.</p><div class="card"><h2>Save your private ticket link</h2><p>Anyone with this link can read and reply to this request. Keep it private. It expires after 90 days, or earlier if the request is deleted.</p><label for="privateLink">Your ticket link</label><input id="privateLink" readonly value="${esc(r.url)}"><button id="copyLink">Copy link</button> <button class="secondary" id="openTicket">View conversation →</button><p class="hint">No email is sent. Save the link before you close this window.</p><p id="status" class="status" role="status"></p></div>`;
  document.getElementById('copyLink').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);status('Private link copied.');}catch{document.getElementById('privateLink').select();status('Select and copy the link above.');}};
  document.getElementById('openTicket').onclick=()=>ticket();
}
function labels(s){return {new:'Received',open:'In progress',waiting:'Waiting for an update',resolved:'Resolved',closed:'Closed'}[s]||s;}
async function ticket() {
  const t=await request(`/customer/tickets/${ticketId}`,{token:capability});
  document.title=t.key+' · Support';
  root.innerHTML=`<span class="eyebrow">${esc(t.project)} · ${esc(t.key)}</span><h1>${esc(t.subject)}</h1><span class="pill" id="ticketState">${esc(labels(t.status))}</span><div class="card"><div class="message">${esc(t.body)}</div><dl class="field-list">${Object.entries(t.fields).filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h2>Conversation</h2><div id="replies"></div><form id="replyForm"><label for="reply">Your reply</label><textarea id="reply" maxlength="2000" required placeholder="Add an update for the support team…"></textarea><button id="sendReply">Send reply</button></form><p id="status" class="status" role="status"></p><button class="secondary" id="refresh">Check for updates</button> <button class="secondary" id="exportTicket">Download my request</button></div><p class="hint">Keep this page’s link private. No email notifications are sent. The link expires ${new Date(Number(t.linkExpiresAt)).toLocaleDateString()}.</p><p class="hint" id="deleteDate"></p>${privacyText(t.privacy)}`;
  function paint(value){if(!capability)return;document.getElementById('deleteDate').textContent=value.deleteAt?'Scheduled deletion: '+new Date(Number(value.deleteAt)).toLocaleString()+'. This date can change with activity or a justified hold.':'';document.getElementById('ticketState').textContent=value.outcome==='cancelled'?'Cancelled':labels(value.status);document.getElementById('replyForm').hidden=value.status==='closed';document.getElementById('replies').innerHTML=value.comments.map(c=>`<article class="reply"><div class="reply-head"><strong>${esc(c.author)}</strong><time>${new Date(Number(c.at)).toLocaleString()}</time></div><p class="message">${esc(c.body)}</p></article>`).join('')||'<p class="hint">Your request has arrived. Replies will appear here.</p>';}
  paint(t);
  let refreshing=false,sending=false,pendingReply=null;
  async function refresh(){if(refreshing||sending||document.hidden)return;refreshing=true;try{paint(await request(`/customer/tickets/${ticketId}`,{token:capability}));status('Up to date.');}catch(e){status(e.message);if(e.status===404){pendingReply=null;unavailable();}}finally{refreshing=false;}}
  document.getElementById('refresh').onclick=refresh;
  document.getElementById('exportTicket').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const data=await request(`/customer/tickets/${ticketId}/export`,{token:capability});if(capability)saveJson(data,`${t.key}-my-request.json`);}catch(e){if(e.status===404)unavailable();else status(e.message);}finally{b.disabled=false;}};
  document.getElementById('replyForm').onsubmit=async e=>{e.preventDefault();if(sending)return;sending=true;const button=document.getElementById('sendReply');button.disabled=true;status('Sending reply…');try{pendingReply ||= {body:document.getElementById('reply').value,requestId:random()};document.getElementById('reply').disabled=true;paint(await request(`/customer/tickets/${ticketId}/replies`,{token:capability,body:pendingReply}));pendingReply=null;document.getElementById('reply').disabled=false;document.getElementById('reply').value='';status('Reply sent.');}catch(err){if(err.status===404){pendingReply=null;unavailable();return;}if(err.status){pendingReply=null;document.getElementById('reply').disabled=false;}status(err.message+(pendingReply?' Retry to confirm this exact reply.':''));}finally{button.disabled=false;sending=false;}};
  clearInterval(poll);poll=setInterval(refresh,30000);
}
async function publicStatus(){
 const stamp=++publicStatusGeneration;clearTimeout(poll);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
 try{const res=await fetch(API.replace('/support/v1','/status/v1/')+encodeURIComponent(parts[1]),{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});if(!res.ok)throw Error('Status page unavailable');const page=await res.json();if(stamp!==publicStatusGeneration)return;document.title=page.title+' · Status';root.innerHTML=renderServiceStatus(page);}
 catch{if(stamp!==publicStatusGeneration)return;root.innerHTML='<h1>Status unavailable</h1><p>Could not retrieve a current status. Please try again shortly.</p>';}
 finally{clearTimeout(timeout);if(stamp===publicStatusGeneration)poll=setTimeout(()=>publicStatus(),60000);}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&parts[0]==='status')publicStatus();});
async function boot(){try{if(parts[0]==='status'&&/^[a-z0-9-]{3,60}$/.test(parts[1]||'')){await publicStatus();return;}if(parts[0]==='form'&&/^[a-f0-9]{64}$/.test(parts[1]||''))await form(parts[1]);else if(parts[0]==='ticket'&&/^\d+$/.test(parts[1]||'')&&/^[a-f0-9]{64}$/.test(parts[2]||'')){ticketId=parts[1];capability=parts[2];await ticket();}else throw new Error('This support link is incomplete. Please use the link provided by the product’s support team.');}catch(e){if(e.status===404&&parts[0]==='ticket'){unavailable();return;}root.innerHTML=`<span class="eyebrow">Customer support</span><h1>We couldn’t open this page.</h1><p>${esc(e.message)}</p><button id="retry">Try again</button>`;document.getElementById('retry').onclick=()=>location.reload();}}
window.addEventListener("hashchange",()=>location.reload());
boot();
